/**
 * FICTIONAL demo reference ranges (Typical / ADHD / Autism) for the trend-chart overlays.
 * Simulated children generated by `npm run demo:references` (prisma/demo-references.ts) —
 * not real data. Shown only where no published reference exists, always labelled fictional,
 * and never used for z-scores or flags. Set DEMO_REFERENCES_ENABLED to false to hide them.
 */
import type { TaskType } from "@/lib/events";
import type { NormBand, ReferenceGroup } from "./index";
import DEMO_JSON from "./demo-references.json";

export const DEMO_REFERENCES_ENABLED = true;

type DemoFile = { fictional: true; note: string; groups: Record<ReferenceGroup, Partial<Record<TaskType, Record<string, NormBand[]>>>> };
const DEMO = DEMO_JSON as DemoFile;

export function demoReferenceBand(taskType: TaskType, metricKey: string, group: ReferenceGroup, age: number): NormBand | null {
  if (!DEMO_REFERENCES_ENABLED) return null;
  return DEMO.groups[group]?.[taskType]?.[metricKey]?.find((b) => age >= b.ageMin && age <= b.ageMax) ?? null;
}
